for node_id, attrs in node_attrs.items():
    if attrs.get('type') in ('Service', 'CustomerFacingService'):
        if attrs.get('tier') == 3:
            tier3_services.add(node_id)

# Find tier-1 services that transitively depend on at least one tier-3 service
result = set()
for tier1_svc in tier1_services:
    # Only check if tier1_svc is in the depends_graph
    if tier1_svc not in depends_graph:
        continue

    # Check if there's a path from tier1_svc to any tier3_svc
    for tier3_svc in tier3_services:
