Looking at this problem, I need to:

1. Load the graph
2. Identify primary nodes (not replicas of anything)
3. Find customer-facing services deployed in reg-3
4. For each service, determine if it would be down when reg-3 fails
5. A service is down if it or any of its transitive dependencies are lost
6. A node is lost if its replica group's footprint contains only reg-3

Let me trace through the logic:
- Find replica groups (connected components via replicaOf edges)
- For each node, compute its footprint (regions where its replica group is deployed)
- A node is lost when reg-3 fails if footprint == {reg-3}
- A service is down if it's lost OR any transitive dependency is lost

```python
import json
from collections import defaultdict, deque

# Load graph
with open('graph.json', 'r') as f:
    graph = json.load(f)

nodes = {node['id']: node for node in graph['nodes']}
edges = graph['edges']

# Build adjacency lists
depends_on = defaultdict(set)  # service -> services it depends on
deployed_in = defaultdict(set)  # node -> regions
replica_of_edges = []  # edges for replica relationships
owned_by = defaultdict(set)

for edge in edges:
    source, relation, target = edge
    if relation == 'dependsOn':
        depends_on[source].add(target)
    elif relation == 'deployedIn':
        deployed_in[source].add(target)
    elif relation == 'replicaOf':
        replica_of_edges.append((source, target))
    elif relation == 'ownedBy':
        owned_by[source].add(target)

# Find replica groups using union-find
parent = {}

def find(x):
    if x not in parent:
        parent[x] = x
    if parent[x] != x:
        parent[x] = find(parent[x])
    return parent[x]

def union(x, y):
    px, py = find(x), find(y)
    if px != py:
        parent[px] = py

for source, target in replica_of_edges:
    union(source, target)

# Group nodes by replica group
replica_groups = defaultdict(set)
for node_id in nodes:
    root = find(node_id)
    replica_groups[root].add(node_id)

# Compute footprint for each node (regions where its replica group is deployed)
footprint = {}
for node_id in nodes:
    root = find(node_id)
    regions = set()
    for member in replica_groups[root]:
        regions.update(deployed_in[member])
    footprint[node_id] = regions

# Identify primary nodes (not replicas)
is_replica = set()
for source, target in replica_of_edges:
    is_replica.add(source)

primary_nodes = {nid for nid in nodes if nid not in is_replica}

# Find customer-facing services in reg-3
cfs_in_reg3 = []
for node_id, node_data in nodes.items():
    if node_data.get('type') == 'CustomerFacingService':
        if node_id in primary_nodes:  # only primary nodes
            if 'reg-3' in deployed_in[node_id]:
                cfs_in_reg3.append(node_id)

# Determine which nodes are lost when reg-3 fails
def is_lost_when_reg3_fails(node_id):
    fp = footprint[node_id]
    return fp == {'reg-3'}

# Compute transitive dependencies
def get_all_dependencies(service_id, visited=None):
    if visited is None:
        visited = set()
    if service_id in visited:
        return visited
    visited.add(service_id)
    for dep in depends_on[service_id]:
        get_all_dependencies(dep, visited)
    return visited

# Check which services are down
services_not_down = []
for service_id in cfs_in_reg3:
    # Check if service itself is lost
    if is_lost_when_reg3_fails(service_id):
        continue

    # Check if any dependency is lost
    all_deps = get_all_dependencies(service_id)
    all_deps.discard(service_id)  # remove self

    is_down = False
    for dep in all_deps:
        if is_lost_when_reg3_fails(dep):
            is_down = True
            break

    if not is_down:
        services_not_down.append(service_id)

services_not_down.sort()
print(json.dumps({"answer_type": "set", "answer": services_not_down}))
```
